CREATE DATABASE IF NOT EXISTS geoguardian CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE geoguardian;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE preferences (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, regionName VARCHAR(255) NOT NULL, coordinates JSON NOT NULL, threshold DECIMAL(8,2) NOT NULL DEFAULT 5, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_preferences_user (user_id)) ENGINE=InnoDB;
CREATE TABLE satellite_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, filename VARCHAR(512) NOT NULL, content_type VARCHAR(100) NOT NULL, image_data MEDIUMBLOB NOT NULL, metadata JSON NULL, parent_id VARCHAR(64) NULL, frame_number INT NULL, frame_date DATE NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_images_parent_frame (parent_id, frame_number)) ENGINE=InnoDB;
CREATE TABLE analyses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, title VARCHAR(255) NOT NULL DEFAULT 'Satellite Analysis', description TEXT, image_file_id BIGINT UNSIGNED NOT NULL, location VARCHAR(255) NOT NULL DEFAULT 'Unknown', bbox JSON NOT NULL, nasaLayer VARCHAR(255) NOT NULL, date DATETIME NOT NULL, analysis_data JSON NULL, status ENUM('completed','pending','error') NOT NULL DEFAULT 'completed', errorMessage TEXT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (image_file_id) REFERENCES satellite_images(id), INDEX idx_analyses_user_created (user_id, createdAt), INDEX idx_analyses_date (date)) ENGINE=InnoDB;
CREATE TABLE monitored_regions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, name VARCHAR(255) NOT NULL, description TEXT, bbox JSON NOT NULL, location VARCHAR(255) NOT NULL DEFAULT 'Unknown', monitoring_enabled BOOLEAN NOT NULL DEFAULT TRUE, monitoring_frequency ENUM('daily','weekly','monthly') NOT NULL DEFAULT 'weekly', alert_on_severity JSON NOT NULL, lastChecked DATETIME NULL, last_image_id BIGINT UNSIGNED NULL, lastChangePercentage DECIMAL(8,2) NOT NULL DEFAULT 0, totalAlertsSent INT UNSIGNED NOT NULL DEFAULT 0, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (last_image_id) REFERENCES satellite_images(id) ON DELETE SET NULL, INDEX idx_regions_user_enabled (user_id, monitoring_enabled), INDEX idx_regions_schedule (monitoring_enabled, monitoring_frequency)) ENGINE=InnoDB;
